cases.bad:
const handleDrop = (e, index) => {
  e.stopPropagation(); // ← always, regardless of whether reorder happened
  if (draggingIndex === null) return; // external drop — but event already swallowed
  // ... reorder logic
};
// External file drop on non-empty area: inner returns early but event blocked
// → outer onFilesDrop never fires → file not added

cases.good:
const handleDrop = (e, index) => {
  if (draggingIndex === null) return; // external drop — let it bubble, NO stopPropagation
  e.stopPropagation(); // internal reorder — swallow to prevent outer misfire
  // ... reorder logic
};
// External drop bubbles to outer → onFilesDrop fires; internal reorder swallowed
